// One short daily report PER PENSION OFFICE workspace, sent to the email that office signed up with.
// Family workspaces and offices with no pensioners get no summary. Test addresses (@example.com) are skipped.
const WS = $('Get workspaces').all().map(i => i.json).filter(w => w.key && w.kind === 'office' && /@/.test(w.email || '') && !/@example\.(com|org|net)$/i.test(w.email));
const URGENT_DAYS = 7;
const zone = 'Asia/Kolkata';
const today = DateTime.now().setZone(zone).startOf('day');
const year = today.year;
const inr = (n) => '₹' + Math.round(n).toLocaleString('en-IN');
const dayIn = v => v ? DateTime.fromISO(typeof v === 'string' ? v : new Date(v).toISOString()).setZone(zone).toISODate() : null;
const allP = $('Get all pensioners').all().map(i => i.json);
const allPay = $('Get all pension payments').all().map(i => i.json);
const allL = $('Get all letters').all().map(i => i.json);
const deadline = DateTime.fromObject({ year, month: 11, day: 30 }, { zone });
const daysLeft = Math.round(deadline.diff(today, 'days').days);

const out = [];
for (const W of WS) {
  const DS = W.key;
  const DA_OLD = Number(W.da_old ?? 55), DA_NEW = Number(W.da_new ?? 58), DA_NEW_FROM = W.da_new_from || '2026-07';
  const pensioners = allP.filter(p => p.name && p.dataset === DS);
  if (!pensioners.length) continue;
  const payments = allPay.filter(r => r.name && r.month && r.dataset === DS);
  const letters = allL.filter(g => g.name && g.dataset === DS);

  const lc = { done: [], not_open_yet: [], open: [], urgent: [], missed: [] };
  for (const p of pensioners) {
    const openDate = DateTime.fromObject({ year, month: p.age >= 80 ? 10 : 11, day: 1 }, { zone });
    const verifiedUntil = dayIn(p.lc_verified_until);
    const submitted = !!verifiedUntil && verifiedUntil > deadline.toISODate();
    let s;
    if (submitted) s = 'done';
    else if (today < openDate) s = 'not_open_yet';
    else if (daysLeft < 0) s = 'missed';
    else if (daysLeft <= URGENT_DAYS) s = 'urgent';
    else s = 'open';
    lc[s].push(p.name);
  }
  const problems = [];
  for (const p of pensioners) {
    let short = 0, missing = 0, shortMonths = 0;
    for (const r of payments.filter(r => r.name === p.name)) {
      const da = r.month >= DA_NEW_FROM ? DA_NEW : DA_OLD;
      const expected = Math.round(r.basic_pension * (1 + da / 100) - (r.commuted_amount || 0));
      const received = Number(r.amount_received) || 0;
      if (received === 0) { missing++; short += expected; }
      else if (expected - received > 0) { shortMonths++; short += expected - received; }
    }
    if (short > 0) problems.push({ name: p.name, short, missing, shortMonths });
  }
  problems.sort((a, b) => b.short - a.short);
  const totalShort = problems.reduce((s, p) => s + p.short, 0);
  const count = (st) => letters.filter(g => g.status === st).length;
  const drafts = letters.filter(g => g.status === 'draft');
  const pending = [...lc.missed, ...lc.urgent, ...lc.open];

  const lines = [];
  lines.push('Pension Helper – Daily Summary for ' + (W.name || 'your office'));
  lines.push(today.toFormat('cccc, d LLLL yyyy'));
  lines.push('');
  lines.push('LIFE CERTIFICATES (deadline 30 November' + (daysLeft >= 0 ? ', ' + daysLeft + ' days left' : ', deadline passed') + ')');
  lines.push('- Verified for this year: ' + lc.done.length + ' of ' + pensioners.length);
  lines.push('- Still to submit: ' + pending.length + (lc.missed.length ? ' (' + lc.missed.length + ' MISSED the deadline)' : ''));
  if (pending.length) lines.push('  ' + pending.join(', '));
  lines.push('');
  lines.push('PENSION PAYMENTS (DA ' + DA_OLD + '% before ' + DA_NEW_FROM + ', ' + DA_NEW + '% from ' + DA_NEW_FROM + ')');
  if (!problems.length) lines.push('- No missing or short payments found in the uploaded statements.');
  else {
    lines.push('- ' + problems.length + ' pensioners have missing or short payments. Total pending: ' + inr(totalShort));
    for (const p of problems) {
      const bits = [];
      if (p.missing) bits.push(p.missing + ' month' + (p.missing > 1 ? 's' : '') + ' not paid');
      if (p.shortMonths) bits.push(p.shortMonths + ' month' + (p.shortMonths > 1 ? 's' : '') + ' paid short');
      lines.push('  • ' + p.name + ': ' + inr(p.short) + ' (' + bits.join(', ') + ')');
    }
  }
  lines.push('');
  lines.push('GRIEVANCE LETTERS');
  lines.push('- Waiting for your approval: ' + drafts.length);
  if (drafts.length) lines.push('  ' + drafts.map(g => g.name + ' (#' + g.id + ')').join(', '));
  lines.push('- Approved: ' + count('approved') + ' | Sent to bank: ' + count('sent') + ' | Resolved: ' + count('resolved') + ' | Rejected: ' + count('rejected'));
  lines.push('');
  lines.push('This summary was prepared automatically by Pension Helper.');

  const subject = 'Pension Helper daily summary – ' + pending.length + ' certificates due, ' + problems.length + ' payment problems, ' + drafts.length + ' letters to approve';
  out.push({ json: { to: W.email, subject, body: lines.join('\n') } });
}
return out;
